"""The .env merge and atomic write: .env holds live secrets and experiment settings, so the setup
script may change only its four variables, must never leave a half-written file, and must keep the
file private (0600)."""

from __future__ import annotations

import fcntl
import io
import os
import stat
import threading
import time
from pathlib import Path

import pytest
from dotenv import dotenv_values
from g2_support import FAKE_KEY, load_setup_provider
from hypothesis import given, settings
from hypothesis import strategies as st

sp = load_setup_provider()

EXISTING = (
    "# Generated by make env\n"
    "RAGFORGE_DB_API_PASSWORD=abc=def==\n"
    "\n"
    "RAGFORGE_LLM_PROVIDER=ollama\n"
    "# RAGFORGE_LLM_PROVIDER=gemini   (a comment, not an assignment)\n"
    "RAGFORGE_LLM_PROVIDER_EXTRA=keep\n"
    "RAGFORGE_AGENT_MAX_TOOL_ROUNDS=0  # arm A1\r\n"
    "RAGFORGE_CHAT_MODEL=llama3.2:3b"  # no trailing newline
)


def _mode(path: Path) -> int:
    return stat.S_IMODE(path.stat().st_mode)


def test_merge_replaces_in_place_and_preserves_every_other_line() -> None:
    merged = sp.merge_env(EXISTING, {"RAGFORGE_LLM_PROVIDER": "gemini"})

    assert merged == EXISTING.replace(
        "RAGFORGE_LLM_PROVIDER=ollama\n", "RAGFORGE_LLM_PROVIDER=gemini\n"
    )


def test_merge_appends_missing_vars_after_fixing_a_missing_final_newline() -> None:
    merged = sp.merge_env(EXISTING, {"RAGFORGE_GEMINI_MODEL": "gemini-2.5-flash"})

    assert merged.startswith(EXISTING + "\n")
    assert merged.endswith("RAGFORGE_GEMINI_MODEL=gemini-2.5-flash\n")
    assert sp.read_env_values(merged)["RAGFORGE_CHAT_MODEL"] == "llama3.2:3b"


def test_merge_collapses_duplicates_so_the_new_value_wins_everywhere() -> None:
    # compose and python-dotenv take the LAST assignment: a stale later duplicate would silently
    # override the value we just wrote.
    text = "RAGFORGE_LLM_PROVIDER=ollama\nA=1\nRAGFORGE_LLM_PROVIDER=ollama\n"

    merged = sp.merge_env(text, {"RAGFORGE_LLM_PROVIDER": "gemini"})

    assert merged == "RAGFORGE_LLM_PROVIDER=gemini\nA=1\n"


def test_merge_preserves_crlf_endings_of_replaced_lines() -> None:
    merged = sp.merge_env("A=1\r\nRAGFORGE_LLM_PROVIDER=ollama\r\n", {"RAGFORGE_LLM_PROVIDER": "x"})

    assert merged == "A=1\r\nRAGFORGE_LLM_PROVIDER=x\r\n"


@pytest.mark.parametrize("value", ["a\nRAGFORGE_KEK=evil", "a\rb"])
def test_merge_refuses_multiline_values(value: str) -> None:
    with pytest.raises(sp.SetupError):
        sp.merge_env("A=1\n", {"RAGFORGE_GEMINI_API_KEY": value})


def test_only_newline_separates_lines() -> None:
    # U+2028 / \v are not line breaks for compose or dotenv: no hidden second assignment.
    text = "NOTE=a\u2028RAGFORGE_LLM_PROVIDER=gemini\nB=\vRAGFORGE_LLM_PROVIDER=x\n"

    assert "RAGFORGE_LLM_PROVIDER" not in sp.read_env_values(text)
    assert sp.merge_env(text, {"RAGFORGE_LLM_PROVIDER": "ollama"}).startswith(text)


def test_read_env_values_last_wins_and_unquotes() -> None:
    values = sp.read_env_values("K=1\nK='2'\n# K=3\nQ=\"x y\"\n")

    assert values == {"K": "2", "Q": "x y"}


_other_line = st.text(
    # \r, \v, U+2028 and friends are allowed on purpose: only '\n' ends a line in .env.
    alphabet=st.characters(codec="utf-8", blacklist_characters="\n"),
    max_size=40,
).filter(lambda line: not set(sp.read_env_values(line)) & set(sp.MANAGED_VARS))


@settings(max_examples=200, deadline=None)
@given(lines=st.lists(_other_line, max_size=12), trailing_newline=st.booleans())
def test_property_unmanaged_lines_survive_any_merge(
    lines: list[str], trailing_newline: bool
) -> None:
    text = "\n".join(lines) + ("\n" if trailing_newline and lines else "")
    updates = {
        "RAGFORGE_LLM_PROVIDER": "gemini",
        "RAGFORGE_GEMINI_API_KEY": FAKE_KEY,
        "RAGFORGE_GEMINI_MODEL": "gemini-2.5-flash",
        "RAGFORGE_GEMINI_THINKING_BUDGET": "0",
    }

    merged = sp.merge_env(text, updates)

    assert merged.startswith(text)  # every pre-existing byte, in order, untouched
    assert {k: sp.read_env_values(merged)[k] for k in updates} == updates


def test_write_is_private_even_when_the_old_file_was_world_readable(tmp_path: Path) -> None:
    env = tmp_path / ".env"
    env.write_text("A=1\n")
    env.chmod(0o644)

    sp.write_env_atomic(env, "A=1\nB=2\n")

    assert env.read_text() == "A=1\nB=2\n"
    assert _mode(env) == 0o600


def test_failed_rename_leaves_the_original_and_no_temp_file(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    env = tmp_path / ".env"
    env.write_text("ORIGINAL=1\n")

    def boom(src: str, dst: str) -> None:
        raise OSError("disk full")

    monkeypatch.setattr(sp.os, "replace", boom)

    with pytest.raises(OSError, match="disk full"):
        sp.write_env_atomic(env, f"RAGFORGE_GEMINI_API_KEY={FAKE_KEY}\n")

    assert env.read_text() == "ORIGINAL=1\n"
    assert sorted(p.name for p in tmp_path.iterdir()) == [".env"]


def test_temp_file_is_private_before_any_secret_is_written(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # The secret must never sit in a group/other-readable file, not even before the rename.
    env = tmp_path / ".env"
    seen_modes: list[int] = []
    real_fdopen = os.fdopen

    def spy_fdopen(fd: int, *args: object, **kwargs: object) -> object:
        seen_modes.append(stat.S_IMODE(os.fstat(fd).st_mode))
        return real_fdopen(fd, *args, **kwargs)  # type: ignore[call-overload]

    monkeypatch.setattr(sp.os, "fdopen", spy_fdopen)

    sp.write_env_atomic(env, f"RAGFORGE_GEMINI_API_KEY={FAKE_KEY}\n")

    assert seen_modes == [0o600]


def test_symlinked_env_updates_the_target_and_keeps_the_link(tmp_path: Path) -> None:
    real = tmp_path / "real.env"
    real.write_text("A=1\n")
    link = tmp_path / ".env"
    link.symlink_to(real)

    sp.write_env_atomic(link, "A=2\n")

    assert link.is_symlink()
    assert real.read_text() == "A=2\n"


def test_without_the_lock_only_stale_temps_are_swept(tmp_path: Path) -> None:
    # Fallback when flock is unavailable: a recent temp file may belong to a concurrent run.
    stale = tmp_path / ".env.setup-dead.tmp"
    fresh = tmp_path / ".env.setup-live.tmp"
    unrelated = tmp_path / ".env.backup.tmp"
    for path in (stale, fresh, unrelated):
        path.write_text(f"RAGFORGE_GEMINI_API_KEY={FAKE_KEY}\n")
    old = time.time() - 3600
    os.utime(stale, (old, old))
    os.utime(unrelated, (old, old))

    sp._sweep_stale_temps(tmp_path, any_age=False)

    assert not stale.exists()
    assert fresh.exists()
    assert unrelated.exists()  # only our own prefix is ever touched


def test_under_the_lock_every_leftover_temp_is_swept_whatever_its_age(tmp_path: Path) -> None:
    # SIGKILL between mkstemp and rename leaves a 0600 key-bearing temp file that neither ignore
    # file excludes. Holding the directory lock proves no other run is mid-write, so even a
    # seconds-old leftover is removed by the next write instead of lingering for ten minutes.
    env = tmp_path / ".env"
    fresh = tmp_path / ".env.setup-killed.tmp"
    unrelated = tmp_path / ".env.backup.tmp"
    for path in (fresh, unrelated):
        path.write_text(f"RAGFORGE_GEMINI_API_KEY={FAKE_KEY}\n")

    sp.write_env_atomic(env, "A=1\n")

    assert not fresh.exists()
    assert unrelated.exists()
    assert sorted(p.name for p in tmp_path.iterdir()) == [".env", ".env.backup.tmp"]


def test_a_write_waits_for_another_run_holding_the_lock(tmp_path: Path) -> None:
    # Two `make setup` runs: the second must not read, merge or rename while the first is between
    # its own read and rename, or one run's update would be lost.
    env = tmp_path / ".env"
    env.write_text("A=1\n")
    done = threading.Event()

    def second_run() -> None:
        sp.update_env(env, {"RAGFORGE_LLM_PROVIDER": "ollama"})
        done.set()

    holder = os.open(tmp_path, os.O_RDONLY)
    try:
        fcntl.flock(holder, fcntl.LOCK_EX)
        worker = threading.Thread(target=second_run)
        worker.start()
        assert not done.wait(0.3)  # blocked while the first run holds the lock
        env.write_text("A=1\nB=written-by-the-first-run\n")
    finally:
        os.close(holder)  # releases the lock
    worker.join(timeout=10)

    assert done.is_set()
    text = env.read_text()
    assert text.startswith("A=1\nB=written-by-the-first-run\n")  # the first run's write survived
    assert sp.read_env_values(text)["RAGFORGE_LLM_PROVIDER"] == "ollama"


# --------------------------------------------- .env is read exactly the way docker compose reads it
# Expected values captured from `docker compose --env-file <file> config` (compose v2, compose-go);
# test_g2_compose_and_make re-checks a subset against the real binary when Docker is available.
COMPOSE_READS = [
    ("A=0   # -1..32768; 0 = thinking off", "0"),
    ("A=x  # personal", "x"),
    ("export A=val", "val"),
    ("  A = spaced", "spaced"),
    ('A="quoted" # c', "quoted"),
    ("A='single # not a comment'", "single # not a comment"),
    ("A=abc#def", "abc#def"),
    ("A=#x", "#x"),
    ("A= #x", "#x"),
    ("A=   # https://aistudio.google.com/apikey", "# https://aistudio.google.com/apikey"),
    ("A=v #a #b", "v"),
    ('A="v"#c', "v"),
    ("A=  spaced val  ", "spaced val"),
    ('A="esc\\"q"', 'esc"q'),
    ('A="a\\nb"', "a\nb"),
    ("A=x\t# tab is not a comment start", "x\t# tab is not a comment start"),
    ("A='x' trailing", "x"),
    ("A=x ## y", "x"),
    ("A=", ""),
]


@pytest.mark.parametrize(("line", "expected"), COMPOSE_READS)
def test_values_are_read_as_compose_reads_them(line: str, expected: str) -> None:
    assert sp.read_env_values(line + "\n") == {"A": expected}


# python-dotenv (what Settings uses outside compose) disagrees with compose only on a value that
# is just a comment, a tab before '#', and text after a closing quote; compose wins there.
_DOTENV_DIFFERS = {"A= #x", "A=   # https://aistudio.google.com/apikey", "A='x' trailing"}


@pytest.mark.parametrize(
    "line",
    [line for line, _ in COMPOSE_READS if line not in _DOTENV_DIFFERS and "\t" not in line],
)
def test_values_match_python_dotenv_where_it_agrees_with_compose(line: str) -> None:
    assert sp.read_env_values(line + "\n") == dict(dotenv_values(stream=io.StringIO(line + "\n")))


def test_merge_swaps_only_the_value_keeping_export_quotes_and_inline_comments() -> None:
    text = (
        'export RAGFORGE_GEMINI_API_KEY="old-key-0123456789abcd"  # personal\n'
        "RAGFORGE_GEMINI_THINKING_BUDGET=0   # -1..32768\n"
        "  RAGFORGE_LLM_PROVIDER = ollama\n"
        "RAGFORGE_GEMINI_MODEL='gemini-2.5-flash' trailing\n"
    )
    updates = {
        "RAGFORGE_GEMINI_API_KEY": FAKE_KEY,
        "RAGFORGE_GEMINI_THINKING_BUDGET": "128",
        "RAGFORGE_LLM_PROVIDER": "gemini",
        "RAGFORGE_GEMINI_MODEL": "gemini-2.5-pro",
    }

    merged = sp.merge_env(text, updates)

    assert merged == (
        f'export RAGFORGE_GEMINI_API_KEY="{FAKE_KEY}"  # personal\n'
        "RAGFORGE_GEMINI_THINKING_BUDGET=128   # -1..32768\n"
        "  RAGFORGE_LLM_PROVIDER = gemini\n"
        "RAGFORGE_GEMINI_MODEL='gemini-2.5-pro' trailing\n"
    )
    assert sp.read_env_values(merged) == updates


def test_merge_replaces_a_value_that_compose_reads_as_a_comment() -> None:
    # `KEY=   # note` is the value "# note" to compose; it must be replaced, not left beside ours.
    merged = sp.merge_env(
        "RAGFORGE_GEMINI_API_KEY=   # get one\n", {"RAGFORGE_GEMINI_API_KEY": FAKE_KEY}
    )

    assert merged == f"RAGFORGE_GEMINI_API_KEY=   {FAKE_KEY}\n"


@pytest.mark.parametrize("value", ["a b", "a#b", "a'b", 'a"b', "a\\b", "$(x)", "${X}"])
def test_merge_refuses_values_that_would_not_read_back_verbatim(value: str) -> None:
    with pytest.raises(sp.SetupError):
        sp.merge_env("A=1\n", {"RAGFORGE_GEMINI_MODEL": value})
